import ctypes, glob, os
lib=ctypes.CDLL("libzstd.so.1")
lib.ZSTD_createDStream.restype=ctypes.c_void_p
lib.ZSTD_initDStream.argtypes=[ctypes.c_void_p]
lib.ZSTD_freeDStream.argtypes=[ctypes.c_void_p]
class Buf(ctypes.Structure):
    _fields_=[("dst",ctypes.c_void_p),("size",ctypes.c_size_t),("pos",ctypes.c_size_t)]
lib.ZSTD_decompressStream.argtypes=[ctypes.c_void_p,ctypes.POINTER(Buf),ctypes.POINTER(Buf)]
lib.ZSTD_decompressStream.restype=ctypes.c_size_t
lib.ZSTD_isError.argtypes=[ctypes.c_size_t]
lib.ZSTD_isError.restype=ctypes.c_uint

def decode(path):
    src=open(path,'rb').read()
    ds=lib.ZSTD_createDStream()
    lib.ZSTD_initDStream(ds)
    inbuf=ctypes.create_string_buffer(src)
    ib=Buf(ctypes.cast(inbuf,ctypes.c_void_p),len(src),0)
    out=[]; CH=1<<16; guard=0
    while True:
        guard+=1
        if guard>100000: raise RuntimeError("loop")
        obuf=ctypes.create_string_buffer(CH)
        ob=Buf(ctypes.cast(obuf,ctypes.c_void_p),CH,0)
        ret=lib.ZSTD_decompressStream(ds,ctypes.byref(ob),ctypes.byref(ib))
        if lib.ZSTD_isError(ret): raise RuntimeError("zstd error")
        if ob.pos: out.append(obuf.raw[:ob.pos])
        if ib.pos>=len(src):
            if ret==0: break
            if ob.pos==0: break
    lib.ZSTD_freeDStream(ds)
    return b''.join(out)

for f in sorted(glob.glob(os.path.expanduser('~/.dsh/sessions/*/*/session.v4.jsonl.zstd'))):
    try:
        t=decode(f).decode('utf-8','replace')
    except Exception as e:
        print("ERR",f,e); continue
    name=f.split('/')[-2]
    print("OK",len(t),name[:12], '讀書會' in t)
    if '讀書會' in t:
        open('/tmp/found_'+name+'.jsonl','w').write(t)
